export const RADIO_CLIPS_BY_CATEGORY = Object.freeze(
  RADIO_CLIPS.reduce((acc, clip) => {
    if (!acc[clip.category]) acc[clip.category] = [];
    acc[clip.category].push(clip);
    return acc;
  }, {}),
);

export const RADIO_CLIPS_BY_ID = Object.freeze(
  RADIO_CLIPS.reduce((acc, clip) => {
    acc[clip.id] = clip;
    return acc;
  }, {}),
);
